{
  "missing_information": [
    {
      "category": "actor",
      "gap": "It is unclear who besides the engineer is involved — specifically who reviews the report, who receives the investigation findings, and whether a coordinator or approver role exists.",
      "why_it_matters": "Automation scope depends on knowing all human roles; handoffs between actors are common bottlenecks and automation targets."
    },
    {
      "category": "decision",
      "gap": "No criteria are defined for what constitutes 'something looks wrong' — the threshold or rule that triggers the investigation branch is unspecified.",
      "why_it_matters": "Without explicit pass/fail or anomaly criteria, it is impossible to automate or even consistently apply the branching logic."
    },
    {
      "category": "system",
      "gap": "The tools used to run the evaluation, record results, and write the report are not identified.",
      "why_it_matters": "Automation feasibility and integration design depend entirely on which systems are involved and whether they expose APIs or data exports."
    },
    {
      "category": "output",
      "gap": "The required format, content, and destination of the report are not described, nor is it clear what artifact the investigation produces.",
      "why_it_matters": "Automating report generation or routing requires knowing the expected structure and delivery channel of each output."
    },
    {
      "category": "exception",
      "gap": "No information is given about what happens if the test cannot be completed — for example, due to equipment failure, missing prerequisites, or unavailable personnel.",
      "why_it_matters": "Exception paths must be modeled to avoid process dead-ends and to design appropriate fallback or escalation automation."
    },
    {
      "category": "frequency",
      "gap": "The rate at which verification tests are requested and whether demand is steady, batch-driven, or event-triggered is unknown.",
      "why_it_matters": "Frequency determines the return on investment for automation and influences whether a queue or scheduling mechanism is needed."
    },
    {
      "category": "manual_effort",
      "gap": "The amount and nature of manual work in preparing the test setup — such as configuring equipment, entering parameters, or copying data — is not described.",
      "why_it_matters": "Identifying high-effort manual steps is essential for prioritizing which parts of the workflow to automate first."
    },
    {
      "category": "input",
      "gap": "The inputs required before the engineer can start — such as a test request identifier, specification document, or configuration parameters — are not specified.",
      "why_it_matters": "Knowing required inputs clarifies prerequisites, enables validation checks, and determines what data must be available at process start."
    }
  ],
  "clarification_questions": [
    {
      "id": "Q1",
      "question": "What specific criteria or thresholds does the engineer use to decide that a result 'looks wrong' and that an investigation is needed rather than proceeding to finalize the report?",
      "targets": ["decision"]
    },
    {
      "id": "Q2",
      "question": "Which tools or systems are used at each stage — for running the evaluation, recording results, and writing the report — and do those systems allow data to be read or written programmatically?",
      "targets": ["system", "integration_constraint"]
    },
    {
      "id": "Q3",
      "question": "Who are all the people involved in this workflow beyond the engineer — for example, is there a reviewer who must approve the report, or a defined list of stakeholders who receive the investigation findings?",
      "targets": ["actor"]
    },
    {
      "id": "Q4",
      "question": "What does the completed report need to contain, in what format is it delivered, and to whom or to which system is it sent when finished?",
      "targets": ["output"]
    },
    {
      "id": "Q5",
      "question": "How often are verification tests requested, and is demand triggered by a scheduled event, a project milestone, or an ad-hoc request from another team?",
      "targets": ["frequency"]
    },
    {
      "id": "Q6",
      "question": "What happens if the test cannot be completed as planned — for instance, if equipment is unavailable or a required input is missing — and who is responsible for resolving that situation?",
      "targets": ["exception"]
    }
  ]
}
